# area: dunder_dispatch
# hypothesis: CPython looks special methods up on the type, so len() and indexing ignore an instance-assigned or annotation-only dunder and __getattr__ does not supply dunders, while an inherited __iter__ works; a checker must reject the unsupported calls.
from collections.abc import Callable, Iterator
from typing import reveal_type


class Base:
    def __iter__(self) -> Iterator[int]:
        return iter((1, 2))


class Child(Base):
    pass


class Lazy:
    __getitem__: Callable[[int], int]  # annotation only, no definition

    def __init__(self) -> None:
        self.__len__ = lambda: 7  # instance attribute, not looked up on the type

    def __getattr__(self, name: str) -> int:
        return 42


def probe_len() -> str:
    obj = Lazy()
    try:
        return str(len(obj))  # expect-error: no __len__ on the type
    except TypeError:
        return 'TypeError'


def probe_getitem() -> str:
    obj = Lazy()
    try:
        return str(obj[0])  # expect-error: __getitem__ is annotation only
    except TypeError:
        return 'TypeError'


def probe_iter() -> int:
    total = 0
    for v in Child():
        total += v
    return total


reveal_type(Child().__iter__())
print(probe_len())
print(probe_getitem())
print(probe_iter())
print(Lazy().anything)
